import urwid
import sys

# Custom characters for LCD (simulate with unicode for demo)
CHECKED_CHAR = u'\u25A3'   # ⎣ (simulate checked box)
UNCHECKED_CHAR = u'\u25A1' # □ (simulate unchecked box)
RADIO_ON_CHAR = u'\u25C9'  # ◉ (simulate radio on)
RADIO_OFF_CHAR = u'\u25CB' # ○ (simulate radio off)
PROGRESS_CHARS = [u'\u2591', u'\u2592', u'\u2593', u'\u2588']  # ░ ▒ ▓ █
SLIDER_LEFT = u'\u25C0'    # ◀
SLIDER_RIGHT = u'\u25B6'   # ▶
SLIDER_KNOB = u'\u25CF'    # ●
MENU_ARROW = u'\u25B6'     # ▶

# Simulate LCD connection
def connect_lcd(port):
    # Placeholder for actual LCD connection logic
    return True

# Custom CheckBox widget
class CustomCheckBox(urwid.WidgetWrap):
    def __init__(self, label, state=False, on_state_change=None):
        self.state = state
        self.label = label
        self.on_state_change = on_state_change
        self._w = urwid.AttrMap(self._get_widget(), None, focus_map='reversed')

    def _get_widget(self):
        char = CHECKED_CHAR if self.state else UNCHECKED_CHAR
        return urwid.Text([char + ' ' + self.label])

    def keypress(self, size, key):
        if key in ('enter', ' '):
            self.state = not self.state
            if self.on_state_change:
                self.on_state_change(self.state)
            self._w.original_widget = self._get_widget()
        return key

    def selectable(self):
        return True

# Custom RadioButton widget
class CustomRadioButton(urwid.WidgetWrap):
    group = []
    def __init__(self, label, state=False, group=None, on_state_change=None):
        self.state = state
        self.label = label
        self.on_state_change = on_state_change
        if group is None:
            self.group = []
        else:
            self.group = group
        self.group.append(self)
        self._w = urwid.AttrMap(self._get_widget(), None, focus_map='reversed')

    def _get_widget(self):
        char = RADIO_ON_CHAR if self.state else RADIO_OFF_CHAR
        return urwid.Text([char + ' ' + self.label])

    def keypress(self, size, key):
        if key in ('enter', ' '):
            for btn in self.group:
                btn.state = False
                btn._w.original_widget = btn._get_widget()
            self.state = True
            if self.on_state_change:
                self.on_state_change(self.label)
            self._w.original_widget = self._get_widget()
        return key

    def selectable(self):
        return True

# Custom ProgressBar widget
class CustomProgressBar(urwid.WidgetWrap):
    def __init__(self, current, done, label=''):
        self.current = current
        self.done = done
        self.label = label
        self._w = urwid.Text(self._get_text())

    def _get_text(self):
        width = 16
        percent = float(self.current) / self.done if self.done else 0
        blocks = int(percent * width)
        bar = ''
        for i in range(width):
            if i < blocks:
                bar += PROGRESS_CHARS[3]
            else:
                bar += PROGRESS_CHARS[0]
        return u'{} [{}] {:>3}%'.format(self.label, bar, int(percent*100))

    def set_progress(self, value):
        self.current = value
        self._w.set_text(self._get_text())

    def selectable(self):
        return False

# Custom Slider widget
class CustomSlider(urwid.WidgetWrap):
    def __init__(self, min_value, max_value, value, label='', on_change=None):
        self.min = min_value
        self.max = max_value
        self.value = value
        self.label = label
        self.on_change = on_change
        self.width = 16
        self._w = urwid.AttrMap(urwid.Text(self._get_text()), None, focus_map='reversed')

    def _get_text(self):
        pos = int((self.value - self.min) / float(self.max - self.min) * (self.width-1))
        bar = SLIDER_LEFT
        for i in range(self.width):
            if i == pos:
                bar += SLIDER_KNOB
            else:
                bar += u'-'
        bar += SLIDER_RIGHT
        return u'{} {}'.format(self.label, bar)

    def keypress(self, size, key):
        if key in ('left', 'h'):
            if self.value > self.min:
                self.value -= 1
                if self.on_change:
                    self.on_change(self.value)
                self._w.original_widget.set_text(self._get_text())
        elif key in ('right', 'l'):
            if self.value < self.max:
                self.value += 1
                if self.on_change:
                    self.on_change(self.value)
                self._w.original_widget.set_text(self._get_text())
        return key

    def selectable(self):
        return True

# Menu system
def menu_button(caption, callback, user_data=None):
    button = urwid.Button([caption, ' ', MENU_ARROW])
    urwid.connect_signal(button, 'click', callback, user_data)
    return urwid.AttrMap(button, None, focus_map='reversed')

def back_button(callback):
    button = urwid.Button(u'Back')
    urwid.connect_signal(button, 'click', callback)
    return urwid.AttrMap(button, None, focus_map='reversed')

class MenuFrame(urwid.WidgetWrap):
    def __init__(self, body, title=''):
        header = urwid.Text(('title', title), align='center')
        frame = urwid.Frame(urwid.AttrMap(body, None), header=header)
        super().__init__(frame)

# Display Settings Menu
def display_settings_menu(parent):
    brightness_slider = CustomSlider(0, 100, 50, label='Brightness:', on_change=None)
    contrast_slider = CustomSlider(0, 100, 50, label='Contrast:', on_change=None)
    items = [
        urwid.Text('Adjust display settings:'),
        urwid.Divider(),
        brightness_slider,
        contrast_slider,
        urwid.Divider(),
        back_button(lambda btn: parent.open_menu('main'))
    ]
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# Cursor Settings Menu
def cursor_settings_menu(parent):
    group = []
    styles = ['None', 'Underline', 'Block', 'Blink']
    items = [urwid.Text('Select cursor style:'), urwid.Divider()]
    for style in styles:
        btn = CustomRadioButton(style, state=(style=='None'), group=group)
        items.append(btn)
    items.append(urwid.Divider())
    items.append(back_button(lambda btn: parent.open_menu('main')))
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# LED Settings Menu
def led_settings_menu(parent):
    led_colors = ['Red', 'Green', 'Blue', 'Yellow']
    sliders = []
    items = [urwid.Text('Adjust LED colors:'), urwid.Divider()]
    for color in led_colors:
        slider = CustomSlider(0, 255, 128, label=color+':', on_change=None)
        sliders.append(slider)
        items.append(slider)
    items.append(urwid.Divider())
    items.append(back_button(lambda btn: parent.open_menu('main')))
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# About Menu
def about_menu(parent):
    text = urwid.Text(
        u"Crystalfontz 635 LCD Demo\n"
        u"--------------------------\n"
        u"This demo shows a menu-driven UI for the Crystalfontz 635 LCD using urwid.\n"
        u"Features:\n"
        u" - Adjust display and LED settings\n"
        u" - Choose cursor style\n"
        u" - Custom widgets for checkboxes, radio buttons, sliders, and progress bars\n"
        u" - LCD connection via command line argument\n"
        u"\nPress 'Back' to return."
    )
    items = [text, urwid.Divider(), back_button(lambda btn: parent.open_menu('main'))]
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# Main Menu
def main_menu(parent):
    items = [
        urwid.Text('Crystalfontz 635 LCD Demo', align='center'),
        urwid.Divider(),
        menu_button('Display Settings', lambda btn: parent.open_menu('display')),
        menu_button('Cursor Settings', lambda btn: parent.open_menu('cursor')),
        menu_button('LED Settings', lambda btn: parent.open_menu('led')),
        menu_button('About this Demo', lambda btn: parent.open_menu('about')),
        urwid.Divider(),
        CustomCheckBox('Demo CheckBox', state=False),
        CustomRadioButton('Demo Radio', state=True, group=[]),
        CustomProgressBar(8, 16, label='Progress:'),
        CustomSlider(0, 100, 50, label='Slider:'),
    ]
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# Main Application

